(window.NOVA_DATA = window.NOVA_DATA || {})["informatics"] = {"id": "informatics", "name": "Информатика", "program": "Типовая учебная программа РК (обновлённое содержание образования). Темы сверять с действующим учебником.", "classes": {"5": {"sections": [{"title": "Компьютер и информация", "topics": [{"id": "i5-info", "title": "Информация и её виды. Информационные процессы", "explain": "Информация — сведения об окружающем мире. По способу восприятия она бывает зрительной, звуковой, обонятельной, вкусовой, осязательной; по форме — текстовой, числовой, графической, звуковой, видео. С информацией выполняют информационные процессы: сбор, хранение, обработку и передачу.", "levels": {"easy": [{"q": "Какая информация воспринимается глазами?", "o": ["зрительная", "звуковая", "вкусовая", "обонятельная"], "a": 0, "e": "Большую часть информации человек получает через зрение."}, {"q": "Что из этого — хранение информации?", "o": ["запись в тетрадь", "разговор по телефону", "решение задачи", "просмотр фильма"], "a": 0, "e": "Информация сохраняется на носителе."}, {"q": "Музыка — информация какой формы?", "o": ["звуковой", "текстовой", "числовой", "графической"], "a": 0, "e": "Воспринимается слухом."}], "medium": [{"q": "Решение примера на калькуляторе — это…", "o": ["обработка информации", "хранение", "сбор", "передача"], "a": 0, "e": "Из исходных данных получаем новые."}, {"q": "Что является носителем информации?", "o": ["флешка", "звук", "мысль", "цвет"], "a": 0, "e": "Материальный объект для хранения."}, {"q": "Отправка сообщения другу — это…", "o": ["передача информации", "хранение", "обработка", "сбор"], "a": 0, "e": "Есть источник, канал и приёмник."}], "hard": [{"q": "Что из перечисленного — канал передачи информации?", "o": ["радиоволны", "книга", "компьютер", "человек"], "a": 0, "e": "Связь между источником и приёмником."}, {"q": "Перевод текста с английского на казахский — это…", "o": ["обработка информации (изменение формы)", "хранение", "сбор", "удаление"], "a": 0, "e": "Меняется форма представления."}, {"q": "Какое свойство информации нарушено, если в прогнозе погоды на сегодня — вчерашние данные?", "o": ["актуальность", "понятность", "полнота", "объективность"], "a": 0, "e": "Информация устарела."}], "olympiad": [{"q": "Почему одна и та же информация может быть полезна одному человеку и бесполезна другому?", "o": ["полезность зависит от задач и знаний получателя", "информация меняется", "это невозможно", "из-за носителя"], "a": 0, "e": "Свойство полезности субъективно."}, {"q": "Что общего у фотографии, нот и чертежа?", "o": ["это графическая форма представления информации", "это звук", "это числа", "это видео"], "a": 0, "e": "Изображения и знаки."}, {"q": "Какой процесс выполняет датчик температуры на метеостанции?", "o": ["сбор информации", "хранение", "уничтожение", "печать"], "a": 0, "e": "Измерение — получение данных."}]}}, {"id": "i5-computer", "title": "Устройство компьютера", "explain": "Компьютер — устройство для работы с информацией. Процессор обрабатывает данные, оперативная память временно хранит данные во время работы, жёсткий диск или SSD хранит данные долго. Устройства ввода: клавиатура, мышь, микрофон, сканер. Устройства вывода: монитор, принтер, колонки. Программы делятся на системные (операционная система) и прикладные.", "levels": {"easy": [{"q": "Устройство ввода?", "o": ["клавиатура", "монитор", "принтер", "колонки"], "a": 0, "e": "Через неё информация поступает в компьютер."}, {"q": "Устройство вывода?", "o": ["принтер", "мышь", "сканер", "микрофон"], "a": 0, "e": "Выводит информацию на бумагу."}, {"q": "«Мозг» компьютера?", "o": ["процессор", "монитор", "мышь", "колонки"], "a": 0, "e": "Обрабатывает данные."}], "medium": [{"q": "Что теряется при выключении компьютера?", "o": ["содержимое оперативной памяти", "файлы на жёстком диске", "файлы на флешке", "фотографии в облаке"], "a": 0, "e": "ОЗУ — энергозависимая память."}, {"q": "Пример операционной системы?", "o": ["Windows", "Word", "Paint", "Chrome"], "a": 0, "e": "Системная программа."}, {"q": "Сенсорный экран — устройство…", "o": ["ввода и вывода одновременно", "только ввода", "только вывода", "хранения"], "a": 0, "e": "Показывает и принимает касания."}], "hard": [{"q": "Где хранятся файлы долго?", "o": ["на жёстком диске или SSD", "в оперативной памяти", "в процессоре", "в мониторе"], "a": 0, "e": "Долговременная память."}, {"q": "Какое устройство переводит бумажный документ в цифровой вид?", "o": ["сканер", "принтер", "монитор", "колонки"], "a": 0, "e": "Устройство ввода."}, {"q": "Чем прикладная программа отличается от системной?", "o": ["решает задачи пользователя (текст, рисунки)", "управляет компьютером", "это одно и то же", "работает без ОС"], "a": 0, "e": "Например, текстовый редактор."}], "olympiad": [{"q": "Почему при сбое питания несохранённый документ пропадает?", "o": ["он находился в оперативной памяти", "он удалился с диска", "его стёр процессор", "из-за монитора"], "a": 0, "e": "Регулярно сохраняйте работу."}, {"q": "Какое устройство нужно для видеозвонка, кроме компьютера и интернета?", "o": ["веб-камера и микрофон", "принтер", "сканер", "флешка"], "a": 0, "e": "Ввод изображения и звука."}, {"q": "Чем SSD лучше старого жёсткого диска?", "o": ["быстрее и без движущихся частей", "дешевле всегда", "больше по размеру", "ничем"], "a": 0, "e": "Флеш-память."}]}}, {"id": "i5-files", "title": "Файлы и папки. Безопасность в интернете", "explain": "Информация на компьютере хранится в файлах. У файла есть имя и расширение, по которому видно тип: .txt — текст, .jpg — изображение, .mp3 — звук, .docx — документ Word. Файлы группируют в папки. В интернете важно соблюдать правила безопасности: не сообщать пароли и личные данные, придумывать надёжные пароли, не открывать подозрительные ссылки.", "levels": {"easy": [{"q": "Какое расширение у изображения?", "o": [".jpg", ".mp3", ".txt", ".exe"], "a": 0, "e": "Фотографии часто в формате JPEG."}, {"q": "Можно ли сообщать пароль незнакомцам в интернете?", "o": ["нет, никогда", "да, если просят вежливо", "да, если это друг друга", "только по почте"], "a": 0, "e": "Пароль — личная тайна."}, {"q": "Для чего нужны папки?", "o": ["чтобы упорядочить файлы", "чтобы ускорить интернет", "чтобы печатать", "чтобы рисовать"], "a": 0, "e": "Удобная структура."}], "medium": [{"q": "Какой пароль надёжнее?", "o": ["K7#mPz!29q", "123456", "qwerty", "ivanov2012"], "a": 0, "e": "Длинный, с разными символами."}, {"q": "Что означает .mp3?", "o": ["звуковой файл", "текст", "картинка", "программа"], "a": 0, "e": "Музыкальный формат."}, {"q": "Пришло письмо «Вы выиграли телефон, введите данные карты». Что делать?", "o": ["не переходить по ссылке и сообщить взрослым", "ввести данные", "переслать друзьям", "ответить"], "a": 0, "e": "Это фишинг."}], "hard": [{"q": "Что такое фишинг?", "o": ["выманивание паролей и данных под видом надёжного сайта", "ловля рыбы", "вирус для принтера", "игра"], "a": 0, "e": "Мошенничество."}, {"q": "Почему файлы с расширением .exe из неизвестных источников опасны?", "o": ["это программы — могут оказаться вирусами", "они большие", "они без звука", "они не открываются"], "a": 0, "e": "Исполняемые файлы."}, {"q": "Что такое путь к файлу?", "o": ["адрес файла: диск и папки, где он лежит", "размер файла", "имя автора", "дата"], "a": 0, "e": "Например, C:\\Учёба\\доклад.docx."}], "olympiad": [{"q": "Почему нельзя использовать один пароль на всех сайтах?", "o": ["при утечке с одного сайта взломают все аккаунты", "так нельзя по закону", "пароль устанет", "можно"], "a": 0, "e": "Разные пароли — разные риски."}, {"q": "Что такое двухфакторная аутентификация?", "o": ["вход с паролем и дополнительным кодом (например, из SMS)", "два пароля подряд", "вход двумя людьми", "два компьютера"], "a": 0, "e": "Повышает защиту."}, {"q": "Что сделать, если в сети тебя оскорбляют (кибербуллинг)?", "o": ["сохранить доказательства, заблокировать, рассказать взрослым", "ответить тем же", "удалить компьютер", "молчать"], "a": 0, "e": "Важно не оставаться одному."}]}}]}, {"title": "Алгоритмы", "topics": [{"id": "i5-algorithms", "title": "Алгоритм. Исполнитель. Линейные алгоритмы", "explain": "Алгоритм — понятная и точная последовательность действий для достижения цели. Исполнитель выполняет команды из своей системы команд (человек, робот, компьютер). Свойства алгоритма: дискретность (шаги), понятность, точность, конечность. Линейный алгоритм — команды выполняются одна за другой. Алгоритмы записывают словами, блок-схемами или на языке программирования.", "levels": {"easy": [{"q": "Что такое алгоритм?", "o": ["точная последовательность действий для решения задачи", "компьютер", "рисунок", "число"], "a": 0, "e": "Определение."}, {"q": "Кто выполняет алгоритм?", "o": ["исполнитель", "автор", "зритель", "клавиатура"], "a": 0, "e": "Человек, робот, компьютер."}, {"q": "Линейный алгоритм — это…", "o": ["команды выполняются по порядку одна за другой", "есть повторения", "есть выбор", "нет команд"], "a": 0, "e": "Без ветвлений и циклов."}], "medium": [{"q": "Какое свойство нарушено, если команда «добавь немного соли»?", "o": ["точность", "конечность", "дискретность", "результативность"], "a": 0, "e": "Непонятно, сколько именно."}, {"q": "Робот стоит в клетке (1; 1). Команды: вправо, вправо, вверх. Где он окажется?", "o": ["(3; 2)", "(2; 3)", "(1; 3)", "(3; 1)"], "a": 0, "e": "x + 2, y + 1."}, {"q": "Какой фигурой в блок-схеме обозначают действие?", "o": ["прямоугольником", "ромбом", "овалом", "треугольником"], "a": 0, "e": "Ромб — условие, овал — начало/конец."}], "hard": [{"q": "Исполнитель умеет «прибавь 3» и «умножь на 2». Как из 1 получить 10?", "o": ["прибавь 3, прибавь 3, прибавь 3", "умножь на 2 трижды", "прибавь 3, умножь на 2", "умножь на 2, прибавь 3"], "a": 0, "e": "1 → 4 → 7 → 10."}, {"q": "Исполнитель: «прибавь 1», «умножь на 3». Что получится из 2 по программе: умножь, прибавь, умножь?", "o": ["21", "18", "9", "12"], "a": 0, "e": "2·3 = 6, +1 = 7, ·3 = 21."}, {"q": "Почему алгоритм должен быть конечным?", "o": ["чтобы получить результат за конечное число шагов", "чтобы был красивым", "чтобы был длинным", "это не обязательно"], "a": 0, "e": "Свойство конечности."}], "olympiad": [{"q": "Исполнитель: «прибавь 2», «умножь на 2». Наименьшее число команд, чтобы из 1 получить 14?", "o": ["4", "3", "5", "2"], "a": 0, "e": "1 → 3 → 5 → 7 → 14 (+2, +2, +2, ×2). За 3 команды получаются только 6, 7, 8, 10 и 12."}, {"q": "В каком порядке выполнять: надеть носки, надеть ботинки, завязать шнурки?", "o": ["носки → ботинки → шнурки", "ботинки → носки → шнурки", "шнурки → носки → ботинки", "любой"], "a": 0, "e": "Порядок команд важен."}, {"q": "Чем блок-схема удобнее словесной записи?", "o": ["наглядно показывает порядок и ветвления", "она короче всегда", "её понимает только компьютер", "ничем"], "a": 0, "e": "Графическая форма."}]}}]}]}, "6": {"sections": [{"title": "Кодирование и графика", "topics": [{"id": "i6-bits", "title": "Кодирование информации. Бит и байт", "explain": "Компьютер хранит любую информацию в виде двоичного кода — последовательности 0 и 1. Наименьшая единица информации — бит (0 или 1). 8 бит = 1 байт. Дальше: 1 Кбайт = 1024 байта, 1 Мбайт = 1024 Кбайт, 1 Гбайт = 1024 Мбайт. С помощью n бит можно закодировать 2ⁿ разных вариантов.", "formula": "1 байт = 8 бит;  1 Кбайт = 1024 байт;  N = 2ⁱ", "check": true, "levels": {"easy": [{"q": "Сколько бит в 1 байте?", "o": ["8", "10", "2", "1024"], "a": 0, "e": "Основное соотношение."}, {"q": "Какие цифры использует двоичный код?", "o": ["0 и 1", "0–9", "1 и 2", "только 1"], "a": 0, "e": "Двоичный алфавит."}, {"q": "Сколько байт в 1 Кбайте?", "o": ["1024", "1000", "8", "100"], "a": 0, "e": "2¹⁰."}], "medium": [{"q": "Сколько вариантов можно закодировать 3 битами?", "o": ["8", "3", "6", "9"], "a": 0, "e": "2³."}, {"q": "Сколько бит в 2 байтах?", "o": ["16", "10", "4", "2048"], "a": 0, "e": "2 · 8."}, {"q": "Что больше: 1 Мбайт или 1000 Кбайт?", "o": ["1 Мбайт", "1000 Кбайт", "равны", "нельзя сравнить"], "a": 0, "e": "1 Мбайт = 1024 Кбайт."}], "hard": [{"q": "Сколько бит нужно, чтобы закодировать 32 цвета?", "o": ["5", "32", "4", "6"], "a": 0, "e": "2⁵ = 32."}, {"q": "Сколько Кбайт в 4096 байтах?", "o": ["4", "40", "0,4", "4096"], "a": 0, "e": "4096 / 1024."}, {"q": "Сколько бит информации в сообщении о выпадении одной стороны монеты?", "o": ["1", "2", "0", "8"], "a": 0, "e": "Два равновероятных варианта."}], "olympiad": [{"q": "Алфавит из 64 символов. Сколько бит нужно на один символ?", "o": ["6", "8", "64", "5"], "a": 0, "e": "2⁶ = 64."}, {"q": "Текст из 100 символов в кодировке 8 бит/символ. Объём в байтах?", "o": ["100", "800", "12,5", "8"], "a": 0, "e": "1 символ = 1 байт."}, {"q": "Сколько разных чисел можно записать 8 битами?", "o": ["256", "255", "8", "128"], "a": 0, "e": "2⁸ = 256 (от 0 до 255)."}]}}, {"id": "i6-graphics", "title": "Компьютерная графика. Растровые и векторные изображения", "explain": "Растровое изображение состоит из пикселей — маленьких точек; при сильном увеличении появляется «лесенка» (фотографии, Paint). Векторное изображение строится из геометрических фигур, описанных формулами; его можно масштабировать без потери качества (логотипы, чертежи). Цвет пикселя задаётся смешением красного, зелёного и синего (RGB).", "levels": {"easy": [{"q": "Из чего состоит растровое изображение?", "o": ["из пикселей", "из линий-формул", "из букв", "из звуков"], "a": 0, "e": "Точки сетки."}, {"q": "Какое изображение можно увеличивать без потери качества?", "o": ["векторное", "растровое", "фотографию", "любое"], "a": 0, "e": "Описано формулами."}, {"q": "Какие три цвета в модели RGB?", "o": ["красный, зелёный, синий", "красный, жёлтый, синий", "чёрный, белый, серый", "голубой, пурпурный, жёлтый"], "a": 0, "e": "Red, Green, Blue."}], "medium": [{"q": "Какой формат — векторный?", "o": [".svg", ".jpg", ".png", ".bmp"], "a": 0, "e": "Scalable Vector Graphics."}, {"q": "Почему фото увеличенное в 10 раз выглядит «кубиками»?", "o": ["становятся видны отдельные пиксели", "фото испортилось", "из-за монитора", "из-за принтера"], "a": 0, "e": "Свойство растра."}, {"q": "Что такое разрешение экрана 1920 × 1080?", "o": ["количество пикселей по ширине и высоте", "размер в сантиметрах", "число цветов", "яркость"], "a": 0, "e": "Full HD."}], "hard": [{"q": "Сколько пикселей на экране 1920 × 1080?", "o": ["2 073 600", "3000", "1 920 000", "20 736"], "a": 0, "e": "1920 · 1080."}, {"q": "Смешение красного и зелёного света на экране даёт…", "o": ["жёлтый", "коричневый", "синий", "чёрный"], "a": 0, "e": "Аддитивная модель."}, {"q": "Какой графический редактор векторный?", "o": ["Inkscape", "Paint", "Фоторедактор телефона", "Блокнот"], "a": 0, "e": "Также CorelDRAW, Illustrator."}], "olympiad": [{"q": "Изображение 10 × 10 пикселей, 256 цветов. Сколько байт оно занимает (без сжатия)?", "o": ["100", "256", "800", "25 600"], "a": 0, "e": "256 цветов = 8 бит = 1 байт на пиксель."}, {"q": "Сколько цветов можно закодировать 24 битами (по 8 на R, G, B)?", "o": ["около 16,7 млн", "256", "24", "65 536"], "a": 0, "e": "2²⁴."}, {"q": "Почему логотипы компаний делают векторными?", "o": ["их нужно печатать и на визитке, и на билборде без потери качества", "они меньше весят всегда", "они цветные", "так красивее"], "a": 0, "e": "Масштабируемость."}]}}]}, {"title": "Алгоритмы и программирование", "topics": [{"id": "i6-branching", "title": "Алгоритмы с ветвлением и повторением", "explain": "Ветвление — выбор действия в зависимости от условия: «если … то … иначе …». Цикл (повторение) — многократное выполнение команд: «повтори N раз» или «пока условие верно». В блок-схеме условие обозначают ромбом. Такие конструкции есть в любой среде программирования, например в Scratch (блоки «если», «повторить», «всегда»).", "check": true, "levels": {"easy": [{"q": "Какой блок-схемой обозначают условие?", "o": ["ромбом", "прямоугольником", "овалом", "кругом"], "a": 0, "e": "Два выхода — «да» и «нет»."}, {"q": "«Если идёт дождь — возьми зонт». Какая это конструкция?", "o": ["ветвление", "цикл", "линейная", "функция"], "a": 0, "e": "Выбор по условию."}, {"q": "«Повтори 10 раз: сделай шаг». Какая конструкция?", "o": ["цикл", "ветвление", "линейная", "переменная"], "a": 0, "e": "Повторение."}], "medium": [{"q": "Сколько раз нарисуется квадрат: «повтори 4 раза: повтори 3 раза: нарисуй квадрат»?", "o": ["12", "7", "4", "3"], "a": 0, "e": "4 · 3."}, {"q": "Робот: «пока впереди свободно — шаг вперёд». Когда он остановится?", "o": ["перед стеной", "через 1 шаг", "никогда", "сразу"], "a": 0, "e": "Цикл с условием."}, {"q": "Число x = 7. «Если x > 5, то x = x − 5, иначе x = x + 5». Результат?", "o": ["2", "12", "7", "5"], "a": 0, "e": "7 > 5 — выполняется первая ветка."}], "hard": [{"q": "Какой угол поворота нужен, чтобы черепашка нарисовала квадрат командой «повтори 4: вперёд 50, поворот …»?", "o": ["90°", "45°", "60°", "120°"], "a": 0, "e": "360° / 4."}, {"q": "Для правильного треугольника черепашка поворачивается на…", "o": ["120°", "60°", "90°", "180°"], "a": 0, "e": "Внешний угол = 360° / 3."}, {"q": "Что выведет алгоритм: n = 1; повтори 3 раза: n = n · 2?", "o": ["8", "6", "3", "4"], "a": 0, "e": "1 → 2 → 4 → 8."}], "olympiad": [{"q": "Сколько раз выполнится тело цикла «пока x < 10: x = x + 3», если x = 1?", "o": ["3", "4", "9", "10"], "a": 0, "e": "1 → 4 → 7 → 10: три раза."}, {"q": "Какой угол поворота для правильного шестиугольника?", "o": ["60°", "120°", "30°", "90°"], "a": 0, "e": "360° / 6."}, {"q": "Что делает блок «всегда» в Scratch?", "o": ["бесконечно повторяет команды", "выполняет один раз", "проверяет условие", "останавливает программу"], "a": 0, "e": "Бесконечный цикл."}]}}, {"id": "i6-docs", "title": "Текстовые документы и презентации", "explain": "Текстовый редактор (Word, Google Документы) позволяет набирать, редактировать и форматировать текст: менять шрифт, размер, выравнивание, вставлять таблицы и рисунки. Презентация (PowerPoint, Google Презентации) — набор слайдов для выступления. Хорошая презентация: мало текста на слайде, крупный шрифт, иллюстрации, единый стиль.", "check": true, "levels": {"easy": [{"q": "Программа для создания презентаций?", "o": ["PowerPoint", "Paint", "Калькулятор", "Блокнот"], "a": 0, "e": "Слайды."}, {"q": "Сочетание клавиш «Копировать»?", "o": ["Ctrl + C", "Ctrl + V", "Ctrl + Z", "Ctrl + P"], "a": 0, "e": "Ctrl + V — вставить."}, {"q": "Что делает Ctrl + Z?", "o": ["отменяет последнее действие", "сохраняет", "печатает", "закрывает окно"], "a": 0, "e": "Undo."}], "medium": [{"q": "Что такое форматирование текста?", "o": ["изменение внешнего вида: шрифт, размер, цвет, выравнивание", "исправление ошибок", "удаление", "сохранение"], "a": 0, "e": "Оформление."}, {"q": "Сколько текста лучше размещать на слайде?", "o": ["немного — ключевые мысли", "весь доклад", "ничего", "как можно больше"], "a": 0, "e": "Слайд — подсказка, а не текст доклада."}, {"q": "Как сохранить документ под другим именем?", "o": ["«Сохранить как»", "«Сохранить»", "«Печать»", "«Закрыть»"], "a": 0, "e": "Создаётся копия."}], "hard": [{"q": "Чем редактирование отличается от форматирования?", "o": ["редактирование меняет содержание, форматирование — вид", "это одно и то же", "форматирование удаляет текст", "редактирование меняет шрифт"], "a": 0, "e": "Разные операции."}, {"q": "Что такое колонтитул?", "o": ["область вверху или внизу страницы, повторяющаяся на всех страницах", "заголовок главы", "сноска", "картинка"], "a": 0, "e": "Например, номер страницы."}, {"q": "Какой формат лучше отправить, чтобы документ выглядел одинаково на любом устройстве?", "o": ["PDF", "DOCX", "TXT", "PPTX"], "a": 0, "e": "Сохраняет вёрстку."}], "olympiad": [{"q": "Почему в презентациях советуют контрастные цвета текста и фона?", "o": ["текст легче читать из зала", "так модно", "так меньше файл", "так требует программа"], "a": 0, "e": "Читаемость."}, {"q": "Что такое «правило 10/20/30» для презентаций?", "o": ["не больше 10 слайдов, 20 минут, шрифт не меньше 30", "10 цветов, 20 картинок, 30 слов", "это правило шрифтов", "такого нет"], "a": 0, "e": "Совет Гая Кавасаки."}, {"q": "Зачем указывать источники картинок и фактов в презентации?", "o": ["уважение авторских прав и проверяемость", "для красоты", "так требует PowerPoint", "не нужно"], "a": 0, "e": "Академическая честность."}]}}]}]}, "7": {"sections": [{"title": "Системы счисления и единицы информации", "topics": [{"id": "i7-number-systems", "title": "Системы счисления. Двоичная система", "explain": "Система счисления — способ записи чисел. В десятичной системе 10 цифр, в двоичной — 2 (0 и 1), в шестнадцатеричной — 16 (0–9 и A–F). Чтобы перевести двоичное число в десятичное, складывают степени двойки, соответствующие единицам: 1011₂ = 8 + 0 + 2 + 1 = 11. Чтобы перевести десятичное в двоичное, делят на 2 и записывают остатки в обратном порядке.", "formula": "1011₂ = 1·2³ + 0·2² + 1·2¹ + 1·2⁰ = 11₁₀", "check": true, "levels": {"easy": [{"q": "Сколько цифр в двоичной системе?", "o": ["2", "10", "8", "16"], "a": 0, "e": "0 и 1."}, {"q": "101₂ в десятичной системе?", "o": ["5", "101", "3", "6"], "a": 0, "e": "4 + 0 + 1."}, {"q": "Как записывается число 2 в двоичной системе?", "o": ["10", "2", "11", "01"], "a": 0, "e": "1·2 + 0."}], "medium": [{"q": "1111₂ = ?", "o": ["15", "4", "16", "1111"], "a": 0, "e": "8 + 4 + 2 + 1."}, {"q": "13₁₀ в двоичной системе?", "o": ["1101", "1011", "1110", "1001"], "a": 0, "e": "8 + 4 + 1."}, {"q": "Сколько цифр в шестнадцатеричной системе?", "o": ["16", "10", "15", "6"], "a": 0, "e": "0–9 и A–F."}], "hard": [{"q": "A₁₆ в десятичной?", "o": ["10", "11", "16", "1"], "a": 0, "e": "A = 10."}, {"q": "100000₂ = ?", "o": ["32", "64", "100", "16"], "a": 0, "e": "2⁵."}, {"q": "Чётное ли число 10111₂?", "o": ["нет — оканчивается на 1", "да", "нельзя сказать", "это не число"], "a": 0, "e": "Последний разряд — 2⁰."}], "olympiad": [{"q": "FF₁₆ = ?", "o": ["255", "256", "1515", "16"], "a": 0, "e": "15·16 + 15."}, {"q": "Сколько единиц в двоичной записи числа 31?", "o": ["5", "4", "31", "1"], "a": 0, "e": "31 = 11111₂."}, {"q": "101₂ + 11₂ = ?", "o": ["1000₂", "112₂", "110₂", "1010₂"], "a": 0, "e": "5 + 3 = 8 = 1000₂."}]}}, {"id": "i7-info-volume", "title": "Измерение информации. Объём текста, изображения, звука", "explain": "Объём текста: I = K · i, где K — число символов, i — бит на символ. Объём изображения: I = (число пикселей) · (бит на пиксель). Объём звука зависит от частоты дискретизации, глубины кодирования, длительности и числа каналов. Скорость передачи данных измеряют в бит/с.", "formula": "I = K · i;  t = I / v", "check": true, "levels": {"easy": [{"q": "Текст из 200 символов по 8 бит. Объём в байтах?", "o": ["200", "1600", "25", "8"], "a": 0, "e": "1 символ = 1 байт."}, {"q": "Скорость 1000 бит/с, файл 8000 бит. Время передачи?", "o": ["8 с", "1 с", "80 с", "0,125 с"], "a": 0, "e": "t = I / v."}, {"q": "Сколько Мбайт в 1 Гбайте?", "o": ["1024", "1000", "8", "100"], "a": 0, "e": "2¹⁰."}], "medium": [{"q": "Текст 2048 символов, 16 бит на символ (Unicode). Объём в Кбайтах?", "o": ["4", "2", "32", "16"], "a": 0, "e": "2048 · 2 байта = 4096 байт."}, {"q": "Изображение 100 × 100 пикселей, 1 бит на пиксель (чёрно-белое). Объём в байтах?", "o": ["1250", "10 000", "100", "800"], "a": 0, "e": "10 000 бит / 8."}, {"q": "Сколько секунд передаётся 1 Мбайт со скоростью 1 Мбит/с?", "o": ["8", "1", "1024", "0,125"], "a": 0, "e": "1 Мбайт = 8 Мбит."}], "hard": [{"q": "Изображение 640 × 480, 256 цветов. Объём в Кбайтах?", "o": ["300", "2400", "480", "640"], "a": 0, "e": "307 200 пикселей · 1 байт = 307 200 байт = 300 Кбайт."}, {"q": "Сколько символов в алфавите, если 1 символ = 5 бит?", "o": ["32", "5", "25", "10"], "a": 0, "e": "2⁵."}, {"q": "Песня 3 мин, 1 Мбайт на минуту. Сколько песен на 1 Гбайт?", "o": ["≈ 341", "≈ 1000", "≈ 33", "≈ 3000"], "a": 0, "e": "1024 / 3."}], "olympiad": [{"q": "Звук: 1 канал, 16 бит, 8000 измерений/с, 10 с. Объём в Кбайтах?", "o": ["≈ 156", "≈ 1280", "≈ 16", "≈ 80"], "a": 0, "e": "8000 · 16 · 10 = 1 280 000 бит = 160 000 байт ≈ 156 Кбайт."}, {"q": "Почему фото в JPEG занимает меньше, чем BMP того же размера?", "o": ["используется сжатие", "меньше пикселей", "меньше цветов всегда", "оно чёрно-белое"], "a": 0, "e": "Сжатие с потерями."}, {"q": "Скорость интернета 100 Мбит/с. Сколько секунд скачивается фильм 1 Гбайт (≈ 8192 Мбит)?", "o": ["≈ 82", "≈ 10", "≈ 1000", "≈ 8"], "a": 0, "e": "8192 / 100."}]}}]}, {"title": "Программирование на Python", "topics": [{"id": "i7-python-basics", "title": "Python: ввод, вывод, переменные, арифметика", "explain": "Python — популярный язык программирования. print() выводит данные, input() считывает строку, int() превращает строку в целое число. Переменная хранит значение: x = 5. Операции: +, −, *, / (деление с дробной частью), // (целочисленное деление), % (остаток), ** (степень).", "formula": "7 // 2 = 3;  7 % 2 = 1;  2 ** 3 = 8;  7 / 2 = 3.5", "check": true, "levels": {"easy": [{"q": "Что выведет print(2 + 3)?", "o": ["5", "2 + 3", "23", "ошибку"], "a": 0, "e": "Сначала вычисляется выражение."}, {"q": "Какая функция считывает ввод с клавиатуры?", "o": ["input()", "print()", "int()", "read()"], "a": 0, "e": "Возвращает строку."}, {"q": "Что выведет print(7 % 2)?", "o": ["1", "3", "3.5", "2"], "a": 0, "e": "Остаток от деления."}], "medium": [{"q": "Что выведет print(7 // 2)?", "o": ["3", "3.5", "4", "1"], "a": 0, "e": "Целая часть частного."}, {"q": "Что выведет print(2 ** 4)?", "o": ["16", "8", "6", "24"], "a": 0, "e": "Возведение в степень."}, {"q": "Что выведет: a = '5'; b = '3'; print(a + b)?", "o": ["53", "8", "ошибку", "5 + 3"], "a": 0, "e": "Строки склеиваются."}], "hard": [{"q": "x = 10; x = x + 5; x = x * 2; print(x)?", "o": ["30", "25", "20", "15"], "a": 0, "e": "15 · 2."}, {"q": "Что выведет print(int('12') + 3)?", "o": ["15", "123", "ошибку", "12 + 3"], "a": 0, "e": "int превращает строку в число."}, {"q": "Что выведет print(10 / 4)?", "o": ["2.5", "2", "2.0", "3"], "a": 0, "e": "Обычное деление даёт дробь."}], "olympiad": [{"q": "a = 17; print(a // 5, a % 5)?", "o": ["3 2", "3.4 2", "2 3", "3 3"], "a": 0, "e": "17 = 5·3 + 2."}, {"q": "Как поменять местами значения a и b в Python одной строкой?", "o": ["a, b = b, a", "a = b; b = a", "swap(a, b)", "a == b"], "a": 0, "e": "Множественное присваивание."}, {"q": "n = 345. Что выведет print(n // 10 % 10)?", "o": ["4", "3", "5", "34"], "a": 0, "e": "345 // 10 = 34, 34 % 10 = 4 — цифра десятков."}]}}, {"id": "i7-python-if", "title": "Python: условный оператор if", "explain": "Условный оператор выполняет код только при выполнении условия. Операции сравнения: ==, !=, <, >, <=, >=. Логические связки: and (и), or (или), not (не). Блок кода внутри if выделяется отступом.", "check": true, "levels": {"easy": [{"q": "Какой оператор сравнения проверяет равенство?", "o": ["==", "=", "!=", "=>"], "a": 0, "e": "Одно = — присваивание."}, {"q": "x = 5; if x > 3: print('да') else: print('нет'). Что выведется?", "o": ["да", "нет", "ошибка", "ничего"], "a": 0, "e": "5 > 3."}, {"q": "Что означает != ?", "o": ["не равно", "равно", "больше", "присвоить"], "a": 0, "e": "Оператор неравенства."}], "medium": [{"q": "x = 4. Что выведет: if x % 2 == 0: print('чётное') else: print('нечётное')?", "o": ["чётное", "нечётное", "4", "ошибку"], "a": 0, "e": "4 делится на 2."}, {"q": "Чем выделяется блок кода внутри if в Python?", "o": ["отступом", "фигурными скобками", "словом end", "точкой с запятой"], "a": 0, "e": "Обычно 4 пробела."}, {"q": "Значение выражения 3 > 2 and 2 > 5?", "o": ["False", "True", "ошибка", "5"], "a": 0, "e": "Второе условие ложно."}], "hard": [{"q": "x = 15. if x > 10: print('A') elif x > 5: print('B') else: print('C'). Вывод?", "o": ["A", "B", "C", "AB"], "a": 0, "e": "Выполняется первая истинная ветка."}, {"q": "Значение not (5 > 3)?", "o": ["False", "True", "5", "3"], "a": 0, "e": "Отрицание истины."}, {"q": "Как проверить, что x в диапазоне от 1 до 10 включительно?", "o": ["1 <= x <= 10", "1 < x < 10", "x > 1 or x < 10", "x == 1..10"], "a": 0, "e": "Python поддерживает двойные сравнения."}], "olympiad": [{"q": "a = 0. Что выведет: if a: print('да') else: print('нет')?", "o": ["нет", "да", "ошибку", "0"], "a": 0, "e": "0 считается ложным значением."}, {"q": "Значение True or False and False?", "o": ["True", "False", "ошибка", "None"], "a": 0, "e": "and выполняется раньше or: True or False."}, {"q": "Год високосный, если делится на 4, но не на 100, или делится на 400. Какое условие верное?", "o": ["y % 4 == 0 and y % 100 != 0 or y % 400 == 0", "y % 4 == 0", "y % 100 == 0", "y % 400 != 0"], "a": 0, "e": "Григорианский календарь."}]}}]}, {"title": "Электронные таблицы", "topics": [{"id": "i7-spreadsheets", "title": "Электронные таблицы: ячейки, формулы, функции", "explain": "Электронная таблица (Excel, Google Таблицы) состоит из ячеек, адрес ячейки — буква столбца и номер строки (B3). Формула начинается со знака «=». Функции: СУММ, СРЗНАЧ, МАКС, МИН. При копировании формулы относительные ссылки (A1) меняются, абсолютные ($A$1) — нет. По данным таблицы строят диаграммы.", "check": true, "levels": {"easy": [{"q": "С какого знака начинается формула?", "o": ["=", "+", "#", "@"], "a": 0, "e": "Иначе это текст."}, {"q": "Адрес ячейки в столбце C и строке 5?", "o": ["C5", "5C", "C-5", "R5C3"], "a": 0, "e": "Буква + номер."}, {"q": "Функция суммы?", "o": ["СУММ (SUM)", "СРЗНАЧ", "МАКС", "СЧЁТ"], "a": 0, "e": "Складывает значения."}], "medium": [{"q": "В A1 = 4, A2 = 6. Значение =СРЗНАЧ(A1:A2)?", "o": ["5", "10", "24", "4"], "a": 0, "e": "Среднее."}, {"q": "В A1 = 3, B1 = 5. Значение =A1*B1+2?", "o": ["17", "21", "10", "16"], "a": 0, "e": "15 + 2."}, {"q": "Сколько ячеек в диапазоне A1:B3?", "o": ["6", "3", "5", "9"], "a": 0, "e": "2 столбца × 3 строки."}], "hard": [{"q": "Формулу =A1+B1 из C1 скопировали в C2. Какой она станет?", "o": ["=A2+B2", "=A1+B1", "=B2+C2", "=A1+B2"], "a": 0, "e": "Относительные ссылки смещаются."}, {"q": "Формулу =$A$1*B1 скопировали из C1 в C3. Какой она станет?", "o": ["=$A$1*B3", "=$A$3*B3", "=$A$1*B1", "=A3*B3"], "a": 0, "e": "Абсолютная ссылка не меняется."}, {"q": "Какую диаграмму выбрать, чтобы показать доли целого?", "o": ["круговую", "линейную", "точечную", "гистограмму"], "a": 0, "e": "Секторы — части целого."}], "olympiad": [{"q": "В A1:A5 числа 2, 4, 6, 8, 10. =МАКС(A1:A5)−МИН(A1:A5)?", "o": ["8", "10", "2", "30"], "a": 0, "e": "10 − 2."}, {"q": "Что вернёт =СЧЁТ(A1:A5), если в ячейках 3, «текст», 5, пусто, 7?", "o": ["3", "5", "4", "15"], "a": 0, "e": "СЧЁТ считает только числа."}, {"q": "Как закрепить в формуле только столбец, но не строку?", "o": ["$A1", "A$1", "$A$1", "A1"], "a": 0, "e": "Смешанная ссылка."}]}}]}]}, "8": {"sections": [{"title": "Логика", "topics": [{"id": "i8-logic", "title": "Основы логики. Логические операции и таблицы истинности", "explain": "Высказывание — утверждение, которое может быть истинным (1) или ложным (0). Основные логические операции: И (конъюнкция, ∧) — истинна, только если оба высказывания истинны; ИЛИ (дизъюнкция, ∨) — истинна, если истинно хотя бы одно; НЕ (инверсия, ¬) — меняет значение на противоположное. Порядок действий: НЕ, затем И, затем ИЛИ.", "check": true, "levels": {"easy": [{"q": "1 ∧ 0 = ?", "o": ["0", "1", "2", "не определено"], "a": 0, "e": "И истинно, только если оба истинны."}, {"q": "1 ∨ 0 = ?", "o": ["1", "0", "2", "10"], "a": 0, "e": "Достаточно одного истинного."}, {"q": "¬1 = ?", "o": ["0", "1", "−1", "2"], "a": 0, "e": "Отрицание."}], "medium": [{"q": "Значение (1 ∨ 0) ∧ 0?", "o": ["0", "1", "2", "не определено"], "a": 0, "e": "1 ∧ 0 = 0."}, {"q": "Сколько строк в таблице истинности для 3 переменных?", "o": ["8", "3", "6", "9"], "a": 0, "e": "2³."}, {"q": "Значение ¬0 ∧ 1?", "o": ["1", "0", "2", "−1"], "a": 0, "e": "¬0 = 1, 1 ∧ 1 = 1."}], "hard": [{"q": "При каком X выражение ¬X ∧ 1 истинно?", "o": ["X = 0", "X = 1", "при любом", "ни при каком"], "a": 0, "e": "¬X должно быть 1."}, {"q": "Сколько наборов (A, B) делают A ∨ B истинным?", "o": ["3", "1", "2", "4"], "a": 0, "e": "Ложно только при 0, 0."}, {"q": "Какое выражение равносильно ¬(A ∧ B)?", "o": ["¬A ∨ ¬B", "¬A ∧ ¬B", "A ∨ B", "A ∧ ¬B"], "a": 0, "e": "Закон де Моргана."}], "olympiad": [{"q": "Какое выражение равносильно ¬(A ∨ B)?", "o": ["¬A ∧ ¬B", "¬A ∨ ¬B", "A ∧ B", "¬A ∨ B"], "a": 0, "e": "Второй закон де Моргана."}, {"q": "Импликация A → B ложна только когда…", "o": ["A = 1, B = 0", "A = 0, B = 1", "A = 0, B = 0", "A = 1, B = 1"], "a": 0, "e": "«Из истины следует ложь» — ложно."}, {"q": "Сколько различных логических функций от 2 переменных?", "o": ["16", "4", "8", "2"], "a": 0, "e": "2^(2²)."}]}}]}, {"title": "Программирование на Python", "topics": [{"id": "i8-loops", "title": "Python: циклы for и while", "explain": "Цикл for перебирает элементы последовательности: for i in range(5) выполнит тело 5 раз (i = 0, 1, 2, 3, 4). range(a, b) даёт числа от a до b − 1, range(a, b, шаг) — с шагом. Цикл while выполняется, пока условие истинно. break досрочно прерывает цикл, continue переходит к следующей итерации.", "check": true, "levels": {"easy": [{"q": "Сколько раз выполнится тело цикла for i in range(4)?", "o": ["4", "3", "5", "0"], "a": 0, "e": "i = 0, 1, 2, 3."}, {"q": "Какие числа даёт range(1, 4)?", "o": ["1, 2, 3", "1, 2, 3, 4", "0, 1, 2, 3", "4"], "a": 0, "e": "Правая граница не включается."}, {"q": "Какой цикл выполняется, пока условие истинно?", "o": ["while", "for", "if", "def"], "a": 0, "e": "Цикл с условием."}], "medium": [{"q": "s = 0; for i in range(1, 5): s += i; print(s)?", "o": ["10", "15", "4", "6"], "a": 0, "e": "1 + 2 + 3 + 4."}, {"q": "Что выведет for i in range(0, 10, 3): print(i, end=' ')?", "o": ["0 3 6 9", "0 3 6 9 12", "3 6 9", "0 3 6"], "a": 0, "e": "Шаг 3, до 9."}, {"q": "Что делает break?", "o": ["прерывает цикл", "пропускает итерацию", "начинает заново", "ничего"], "a": 0, "e": "Досрочный выход."}], "hard": [{"q": "n = 1; while n < 100: n *= 3; print(n)?", "o": ["243", "81", "100", "729"], "a": 0, "e": "1 → 3 → 9 → 27 → 81 → 243."}, {"q": "Сколько раз выполнится: i = 10; while i > 0: i -= 3?", "o": ["4", "3", "10", "бесконечно"], "a": 0, "e": "10 → 7 → 4 → 1 → −2."}, {"q": "p = 1; for i in range(1, 6): p *= i; print(p)?", "o": ["120", "15", "720", "24"], "a": 0, "e": "5! = 120."}], "olympiad": [{"q": "Сумма цифр: n = 4096; s = 0; while n > 0: s += n % 10; n //= 10. Чему равно s?", "o": ["19", "4096", "4", "13"], "a": 0, "e": "4 + 0 + 9 + 6."}, {"q": "Что выведет: for i in range(5): if i == 3: continue; print(i, end='')?", "o": ["0124", "012", "01234", "3"], "a": 0, "e": "Итерация с 3 пропускается."}, {"q": "Когда цикл while становится бесконечным?", "o": ["если условие никогда не становится ложным", "если в нём есть print", "если нет отступа", "никогда"], "a": 0, "e": "Например, забыли изменить переменную."}]}}, {"id": "i8-lists", "title": "Python: списки", "explain": "Список хранит несколько значений: a = [3, 1, 4]. Индексы начинаются с 0: a[0] = 3, a[-1] — последний элемент. len(a) — длина списка. Методы: append (добавить в конец), sort (сортировать), функции sum, max, min. Срез a[1:3] даёт элементы с индексами 1 и 2.", "check": true, "levels": {"easy": [{"q": "a = [5, 7, 9]. Чему равно a[0]?", "o": ["5", "7", "9", "0"], "a": 0, "e": "Нумерация с нуля."}, {"q": "Что возвращает len([1, 2, 3, 4])?", "o": ["4", "3", "10", "1"], "a": 0, "e": "Количество элементов."}, {"q": "Какой метод добавляет элемент в конец списка?", "o": ["append", "add", "push", "insert_end"], "a": 0, "e": "a.append(x)."}], "medium": [{"q": "a = [3, 8, 2]. print(a[-1])?", "o": ["2", "3", "8", "ошибку"], "a": 0, "e": "Отрицательный индекс — с конца."}, {"q": "a = [4, 1, 3]; a.sort(); print(a)?", "o": ["[1, 3, 4]", "[4, 3, 1]", "[4, 1, 3]", "ошибку"], "a": 0, "e": "Сортировка по возрастанию."}, {"q": "sum([2, 4, 6])?", "o": ["12", "6", "246", "3"], "a": 0, "e": "Сумма элементов."}], "hard": [{"q": "a = [10, 20, 30, 40]. print(a[1:3])?", "o": ["[20, 30]", "[10, 20, 30]", "[20, 30, 40]", "[10, 20]"], "a": 0, "e": "Индексы 1 и 2."}, {"q": "a = [1, 2, 3]; a.append(4); print(len(a))?", "o": ["4", "3", "5", "1"], "a": 0, "e": "Добавили элемент."}, {"q": "Что выведет print([i * 2 for i in range(3)])?", "o": ["[0, 2, 4]", "[2, 4, 6]", "[0, 1, 2]", "[1, 2, 3]"], "a": 0, "e": "Генератор списка."}], "olympiad": [{"q": "a = [5, 3, 8, 1]. Как найти индекс максимального элемента?", "o": ["a.index(max(a))", "max(a)", "a[max]", "len(a)"], "a": 0, "e": "Сначала максимум, затем его индекс."}, {"q": "a = [1, 2, 3]; b = a; b.append(4); print(a)?", "o": ["[1, 2, 3, 4]", "[1, 2, 3]", "ошибку", "[4]"], "a": 0, "e": "b — ссылка на тот же список."}, {"q": "print([1, 2, 3][::-1])?", "o": ["[3, 2, 1]", "[1, 2, 3]", "[1]", "ошибку"], "a": 0, "e": "Срез с шагом −1 разворачивает."}]}}]}, {"title": "Компьютерные сети", "topics": [{"id": "i8-networks", "title": "Компьютерные сети и интернет", "explain": "Сеть объединяет компьютеры для обмена данными: локальная (в здании), глобальная (интернет). Каждое устройство в интернете имеет IP-адрес; доменные имена (например, edu.kz) переводятся в IP-адреса службой DNS. Сайты передаются по протоколу HTTP/HTTPS, где S означает защищённое шифрованием соединение. Адрес страницы — URL.", "check": true, "levels": {"easy": [{"q": "Что означает «S» в HTTPS?", "o": ["защищённое (шифрованное) соединение", "быстрое", "старое", "спортивное"], "a": 0, "e": "Secure."}, {"q": "Глобальная сеть, объединяющая миллионы компьютеров?", "o": ["интернет", "локальная сеть", "Bluetooth", "USB"], "a": 0, "e": "Сеть сетей."}, {"q": "Какой домен верхнего уровня у Казахстана?", "o": [".kz", ".ka", ".kaz", ".ru"], "a": 0, "e": "Также .қаз."}], "medium": [{"q": "Что делает DNS?", "o": ["переводит доменные имена в IP-адреса", "шифрует пароли", "ускоряет компьютер", "удаляет вирусы"], "a": 0, "e": "Как телефонная книга интернета."}, {"q": "Что такое IP-адрес?", "o": ["уникальный адрес устройства в сети", "пароль", "название сайта", "браузер"], "a": 0, "e": "Например, 192.168.1.1."}, {"q": "Что такое браузер?", "o": ["программа для просмотра сайтов", "сайт", "поисковик", "антивирус"], "a": 0, "e": "Chrome, Firefox, Edge."}], "hard": [{"q": "Сколько чисел в IPv4-адресе и в каком диапазоне каждое?", "o": ["4 числа от 0 до 255", "3 числа от 0 до 999", "6 чисел", "любое количество"], "a": 0, "e": "Например, 10.0.0.1."}, {"q": "Что такое маршрутизатор (роутер)?", "o": ["устройство, передающее данные между сетями", "монитор", "клавиатура", "принтер"], "a": 0, "e": "Wi-Fi-роутер дома."}, {"q": "Чем локальная сеть отличается от глобальной?", "o": ["охватывает небольшую территорию", "она быстрее всегда", "в ней нет компьютеров", "ничем"], "a": 0, "e": "Школа, офис."}], "olympiad": [{"q": "Почему по IPv4 адресов уже не хватает?", "o": ["их всего около 4,3 млрд (2³²)", "их слишком много", "их отменили", "хватает"], "a": 0, "e": "Переход на IPv6."}, {"q": "Какая часть URL https://edu.kz/math/index.html — доменное имя?", "o": ["edu.kz", "https", "math", "index.html"], "a": 0, "e": "Остальное — протокол и путь."}, {"q": "Почему передавать пароль на сайт без HTTPS опасно?", "o": ["его могут перехватить в открытом виде", "сайт не откроется", "пароль станет короче", "не опасно"], "a": 0, "e": "Нет шифрования."}]}}]}]}, "9": {"sections": [{"title": "Алгоритмы и программирование", "topics": [{"id": "i9-functions", "title": "Python: функции", "explain": "Функция — именованный блок кода, который можно вызывать много раз. Её объявляют словом def, у неё могут быть параметры, а return возвращает результат. Функции делают программу короче и понятнее. Переменные внутри функции локальные — они не видны снаружи.", "check": true, "levels": {"easy": [{"q": "Каким словом объявляют функцию в Python?", "o": ["def", "func", "function", "fun"], "a": 0, "e": "def имя(параметры):"}, {"q": "Что делает return?", "o": ["возвращает значение из функции", "выводит на экран", "прерывает цикл", "считывает ввод"], "a": 0, "e": "Результат функции."}, {"q": "def f(x): return x * 2. Чему равно f(5)?", "o": ["10", "7", "25", "5"], "a": 0, "e": "5 · 2."}], "medium": [{"q": "def s(a, b): return a + b. print(s(3, 4))?", "o": ["7", "34", "12", "ошибку"], "a": 0, "e": "Сумма параметров."}, {"q": "Что вернёт функция без return?", "o": ["None", "0", "ошибку", "пустую строку"], "a": 0, "e": "Значение по умолчанию."}, {"q": "def f(n): return n % 2 == 0. Что вернёт f(7)?", "o": ["False", "True", "1", "7"], "a": 0, "e": "7 нечётное."}], "hard": [{"q": "def f(x): return x * x. print(f(f(2)))?", "o": ["16", "4", "8", "2"], "a": 0, "e": "f(2) = 4, f(4) = 16."}, {"q": "Что такое локальная переменная?", "o": ["переменная, видимая только внутри функции", "глобальная константа", "параметр цикла", "переменная в другом файле"], "a": 0, "e": "Область видимости."}, {"q": "def g(a, b=10): return a + b. g(5)?", "o": ["15", "5", "ошибку", "510"], "a": 0, "e": "Параметр по умолчанию."}], "olympiad": [{"q": "def fact(n): return 1 if n <= 1 else n * fact(n - 1). fact(5)?", "o": ["120", "15", "24", "5"], "a": 0, "e": "Рекурсия: 5!"}, {"q": "def fib(n): return n if n < 2 else fib(n-1) + fib(n-2). fib(6)?", "o": ["8", "5", "13", "6"], "a": 0, "e": "0, 1, 1, 2, 3, 5, 8."}, {"q": "Почему рекурсивный fib(40) считается очень долго?", "o": ["одни и те же значения вычисляются много раз", "компьютер слабый", "рекурсия запрещена", "из-за print"], "a": 0, "e": "Экспоненциальное число вызовов."}]}}, {"id": "i9-sorting", "title": "Алгоритмы поиска и сортировки", "explain": "Линейный поиск перебирает элементы по очереди. Бинарный поиск работает в отсортированном массиве: каждый раз делит область поиска пополам, поэтому очень быстр (около log₂ n шагов). Простые сортировки — пузырьком (соседние элементы меняются местами) и выбором (ищем минимум и ставим в начало). В Python есть встроенная sorted().", "check": true, "levels": {"easy": [{"q": "Для какого поиска массив должен быть отсортирован?", "o": ["бинарного", "линейного", "любого", "никакого"], "a": 0, "e": "Деление пополам."}, {"q": "Что делает сортировка?", "o": ["упорядочивает элементы", "удаляет элементы", "считает сумму", "переворачивает список"], "a": 0, "e": "По возрастанию или убыванию."}, {"q": "sorted([3, 1, 2])?", "o": ["[1, 2, 3]", "[3, 2, 1]", "[3, 1, 2]", "6"], "a": 0, "e": "Возвращает новый список."}], "medium": [{"q": "Сколько сравнений максимум нужно бинарному поиску в массиве из 1024 элементов?", "o": ["около 10", "1024", "512", "100"], "a": 0, "e": "log₂ 1024 = 10."}, {"q": "Как работает сортировка пузырьком?", "o": ["сравнивает соседние элементы и меняет местами неупорядоченные", "делит массив пополам", "выбирает случайный элемент", "копирует массив"], "a": 0, "e": "Большие «всплывают» в конец."}, {"q": "sorted([3, 1, 2], reverse=True)?", "o": ["[3, 2, 1]", "[1, 2, 3]", "[2, 1, 3]", "ошибку"], "a": 0, "e": "По убыванию."}], "hard": [{"q": "Сколько шагов в худшем случае делает линейный поиск в массиве из n элементов?", "o": ["n", "log₂ n", "1", "n²"], "a": 0, "e": "Нужно проверить все."}, {"q": "После первого прохода пузырька по [5, 1, 4, 2] массив станет…", "o": ["[1, 4, 2, 5]", "[1, 2, 4, 5]", "[5, 4, 2, 1]", "[1, 5, 4, 2]"], "a": 0, "e": "Максимум 5 оказывается в конце."}, {"q": "Сколько сравнений делает сортировка пузырьком для n элементов примерно?", "o": ["около n²/2", "n", "log n", "1"], "a": 0, "e": "Квадратичная сложность."}], "olympiad": [{"q": "Почему быстрая сортировка (quicksort) обычно быстрее пузырька?", "o": ["в среднем около n·log n операций против n²", "она проще", "она использует меньше памяти всегда", "это не так"], "a": 0, "e": "Сложность алгоритмов."}, {"q": "Загадали число от 1 до 100. Сколько вопросов «больше/меньше» гарантированно хватит?", "o": ["7", "10", "50", "100"], "a": 0, "e": "2⁷ = 128 ≥ 100."}, {"q": "Что такое устойчивая сортировка?", "o": ["сохраняет порядок равных элементов", "не ломается", "работает быстро", "сортирует только числа"], "a": 0, "e": "Важно при сортировке по нескольким ключам."}]}}]}, {"title": "Базы данных и веб", "topics": [{"id": "i9-databases", "title": "Базы данных", "explain": "База данных — организованное хранилище информации. В реляционной БД данные хранятся в таблицах: строки — записи, столбцы — поля. Первичный ключ однозначно определяет запись (например, номер ученика). Системы управления БД (СУБД) позволяют искать, сортировать, фильтровать данные; для запросов используют язык SQL.", "check": true, "levels": {"easy": [{"q": "Как называется строка таблицы базы данных?", "o": ["запись", "поле", "ключ", "ячейка"], "a": 0, "e": "Одна сущность."}, {"q": "Как называется столбец таблицы БД?", "o": ["поле", "запись", "файл", "индекс"], "a": 0, "e": "Например, «Фамилия»."}, {"q": "Что такое СУБД?", "o": ["программа для управления базами данных", "вид компьютера", "сайт", "сеть"], "a": 0, "e": "MySQL, PostgreSQL, Access."}], "medium": [{"q": "Что такое первичный ключ?", "o": ["поле, однозначно определяющее запись", "любое поле", "пароль", "первая строка"], "a": 0, "e": "Например, ИИН."}, {"q": "Почему ИИН подходит для ключа, а фамилия — нет?", "o": ["ИИН уникален, фамилии повторяются", "ИИН короче", "фамилия длинная", "это не так"], "a": 0, "e": "Уникальность."}, {"q": "Какой язык используют для запросов к БД?", "o": ["SQL", "HTML", "CSS", "Scratch"], "a": 0, "e": "Structured Query Language."}], "hard": [{"q": "Что делает запрос SELECT * FROM students?", "o": ["выбирает все записи таблицы students", "удаляет таблицу", "создаёт таблицу", "сортирует"], "a": 0, "e": "* — все поля."}, {"q": "Как выбрать учеников 9 класса?", "o": ["SELECT * FROM students WHERE grade = 9", "SELECT 9 FROM students", "DELETE grade 9", "GET students 9"], "a": 0, "e": "Условие WHERE."}, {"q": "Что делает ORDER BY name?", "o": ["сортирует результат по имени", "удаляет имена", "группирует", "считает"], "a": 0, "e": "Сортировка."}], "olympiad": [{"q": "Что такое связь «один ко многим»?", "o": ["одной записи одной таблицы соответствует много записей другой", "один ученик — одна оценка", "многие ко многим", "нет связи"], "a": 0, "e": "Класс — много учеников."}, {"q": "Зачем базы данных разбивают на несколько таблиц (нормализация)?", "o": ["чтобы избежать дублирования и ошибок", "чтобы было сложнее", "для красоты", "не нужно"], "a": 0, "e": "Каждый факт хранится один раз."}, {"q": "SELECT COUNT(*) FROM students WHERE grade = 9 возвращает…", "o": ["число учеников 9 класса", "список имён", "средний балл", "ошибку"], "a": 0, "e": "Агрегатная функция."}]}}, {"id": "i9-web", "title": "Создание веб-страниц: HTML и CSS", "explain": "Веб-страницы пишут на языке разметки HTML: теги обозначают структуру — заголовки <h1>, абзацы <p>, ссылки <a href>, изображения <img src>, списки <ul>/<li>. Внешний вид задаёт CSS: цвет, шрифт, отступы, расположение. Интерактивность добавляет язык программирования JavaScript.", "check": true, "levels": {"easy": [{"q": "Язык разметки веб-страниц?", "o": ["HTML", "Python", "SQL", "Excel"], "a": 0, "e": "HyperText Markup Language."}, {"q": "Тег главного заголовка?", "o": ["<h1>", "<p>", "<a>", "<img>"], "a": 0, "e": "Заголовок первого уровня."}, {"q": "Что задаёт внешний вид страницы?", "o": ["CSS", "HTML", "SQL", "DNS"], "a": 0, "e": "Каскадные таблицы стилей."}], "medium": [{"q": "Какой тег создаёт ссылку?", "o": ["<a href='...'>", "<link>", "<p>", "<h1>"], "a": 0, "e": "Гиперссылка."}, {"q": "Какой тег вставляет картинку?", "o": ["<img src='...'>", "<pic>", "<image>", "<src>"], "a": 0, "e": "Атрибут src — путь к файлу."}, {"q": "Что делает JavaScript на странице?", "o": ["добавляет интерактивность", "задаёт только цвет", "хранит базу данных", "переводит адреса"], "a": 0, "e": "Язык программирования для браузера."}], "hard": [{"q": "CSS-правило p { color: red; } делает…", "o": ["текст всех абзацев красным", "фон красным", "заголовки красными", "ничего"], "a": 0, "e": "Селектор p."}, {"q": "Какой тег создаёт маркированный список?", "o": ["<ul>", "<ol>", "<li> без обёртки", "<list>"], "a": 0, "e": "<ol> — нумерованный."}, {"q": "Что такое адаптивная вёрстка?", "o": ["страница хорошо выглядит на экранах разного размера", "страница без картинок", "страница только для ПК", "печатная версия"], "a": 0, "e": "Media queries."}], "olympiad": [{"q": "Что такое атрибут alt у тега <img>?", "o": ["альтернативный текст для изображения (доступность)", "размер картинки", "цвет", "ссылка"], "a": 0, "e": "Читается экранными читалками."}, {"q": "В CSS что имеет больший приоритет: селектор по id (#menu) или по классу (.menu)?", "o": ["по id", "по классу", "одинаково", "по тегу"], "a": 0, "e": "Специфичность селекторов."}, {"q": "Почему пароли нельзя проверять только в JavaScript на странице?", "o": ["код в браузере может изменить любой пользователь", "JavaScript медленный", "это запрещено", "можно"], "a": 0, "e": "Проверка — на сервере."}]}}]}]}, "10": {"sections": [{"title": "Архитектура и представление данных", "topics": [{"id": "i10-architecture", "title": "Архитектура компьютера", "explain": "Большинство компьютеров построены по принципам фон Неймана: программа и данные хранятся в общей памяти в двоичном виде, процессор выполняет команды последовательно. Процессор содержит арифметико-логическое устройство и устройство управления, работает с тактовой частотой (ГГц) и имеет несколько ядер. Иерархия памяти: регистры → кэш → ОЗУ → внешняя память (чем быстрее, тем меньше объём).", "check": true, "levels": {"easy": [{"q": "Кто сформулировал основные принципы устройства ЭВМ?", "o": ["Джон фон Нейман", "Билл Гейтс", "Стив Джобс", "Алан Тьюринг"], "a": 0, "e": "1945 год."}, {"q": "Какая память самая быстрая?", "o": ["регистры процессора", "жёсткий диск", "флешка", "облако"], "a": 0, "e": "Внутри процессора."}, {"q": "В чём измеряют тактовую частоту процессора?", "o": ["в гигагерцах", "в гигабайтах", "в ваттах", "в пикселях"], "a": 0, "e": "Количество тактов в секунду."}], "medium": [{"q": "Что такое кэш-память?", "o": ["быстрая память между процессором и ОЗУ", "жёсткий диск", "облачное хранилище", "монитор"], "a": 0, "e": "Хранит часто используемые данные."}, {"q": "Принцип хранимой программы означает…", "o": ["программа хранится в памяти вместе с данными", "программа на бумаге", "программа в процессоре навсегда", "нет программы"], "a": 0, "e": "Фон Нейман."}, {"q": "Зачем процессору несколько ядер?", "o": ["выполнять несколько задач параллельно", "для красоты", "для охлаждения", "чтобы больше памяти"], "a": 0, "e": "Многоядерность."}], "hard": [{"q": "Что делает АЛУ?", "o": ["выполняет арифметические и логические операции", "хранит файлы", "выводит изображение", "управляет сетью"], "a": 0, "e": "Часть процессора."}, {"q": "Что такое разрядность процессора (64 бита)?", "o": ["размер данных, обрабатываемых за одну операцию", "число ядер", "частота", "объём памяти"], "a": 0, "e": "64-битные системы адресуют больше памяти."}, {"q": "Что такое BIOS/UEFI?", "o": ["программа начальной загрузки компьютера", "антивирус", "браузер", "текстовый редактор"], "a": 0, "e": "Запускается при включении."}], "olympiad": [{"q": "Почему увеличение частоты процессоров замедлилось после ~2005 года?", "o": ["рост тепловыделения — выгоднее добавлять ядра", "закончился кремний", "это запрещено", "частота растёт как раньше"], "a": 0, "e": "Энергопотребление и нагрев."}, {"q": "Что такое закон Мура?", "o": ["число транзисторов в микросхемах примерно удваивается каждые два года", "скорость интернета растёт", "цена компьютеров падает", "закон о защите данных"], "a": 0, "e": "Наблюдение Гордона Мура."}, {"q": "Чем отличается гарвардская архитектура от фон-неймановской?", "o": ["память программ и данных разделена", "нет процессора", "нет памяти", "ничем"], "a": 0, "e": "Используется в микроконтроллерах."}]}}, {"id": "i10-encoding", "title": "Кодирование текста, изображений и звука", "explain": "Текст кодируют таблицами символов: ASCII (128 символов, 7 бит), Unicode (UTF-8 — от 1 до 4 байт на символ, поддерживает все алфавиты, включая казахский). Изображения кодируют пикселями с глубиной цвета i бит (2ⁱ цветов). Звук оцифровывают: частота дискретизации (сколько измерений в секунду) и глубина кодирования (бит на измерение).", "formula": "Изображение: I = W·H·i;  звук: I = f·i·t·k (k — число каналов)", "check": true, "levels": {"easy": [{"q": "Какая кодировка поддерживает буквы всех языков?", "o": ["Unicode", "ASCII", "двоичная", "азбука Морзе"], "a": 0, "e": "UTF-8 — самая популярная."}, {"q": "Сколько символов в таблице ASCII?", "o": ["128", "256", "1024", "33"], "a": 0, "e": "7 бит."}, {"q": "Что такое частота дискретизации?", "o": ["число измерений звука в секунду", "громкость", "длительность", "размер файла"], "a": 0, "e": "Например, 44,1 кГц."}], "medium": [{"q": "Сколько цветов при глубине цвета 16 бит?", "o": ["65 536", "16", "256", "1024"], "a": 0, "e": "2¹⁶."}, {"q": "Изображение 1024 × 768, 24 бита на пиксель. Объём в Мбайтах?", "o": ["2,25", "24", "0,75", "18"], "a": 0, "e": "1024·768·3 = 2 359 296 байт = 2,25 Мбайт."}, {"q": "Почему казахские буквы (ә, ғ, қ) часто «ломаются» в старых программах?", "o": ["их нет в старых 8-битных кодировках", "они слишком сложные", "из-за шрифта всегда", "не ломаются"], "a": 0, "e": "Нужен Unicode."}], "hard": [{"q": "Стерео, 44 100 Гц, 16 бит, 60 с. Объём примерно?", "o": ["≈ 10 Мбайт", "≈ 1 Мбайт", "≈ 100 Мбайт", "≈ 5 Мбайт"], "a": 0, "e": "44 100·2·2·60 ≈ 10,6 млн байт."}, {"q": "Сколько байт занимает латинская буква в UTF-8?", "o": ["1", "2", "4", "8"], "a": 0, "e": "Совместимость с ASCII."}, {"q": "Что такое сжатие с потерями?", "o": ["часть информации удаляется ради меньшего размера (JPEG, MP3)", "архив ZIP", "сжатие без изменений", "удаление файла"], "a": 0, "e": "Незаметные человеку детали."}], "olympiad": [{"q": "Почему ZIP-архив текста сильно меньше, а архив JPEG почти не уменьшается?", "o": ["JPEG уже сжат, в тексте много повторов", "JPEG не сжимается в принципе", "ZIP не работает с картинками", "это не так"], "a": 0, "e": "Избыточность данных."}, {"q": "Сколько бит нужно для кодирования 26 букв?", "o": ["5", "26", "4", "8"], "a": 0, "e": "2⁵ = 32 ≥ 26."}, {"q": "Что такое RLE-сжатие?", "o": ["запись повторов как «символ × количество»", "шифрование", "сжатие звука", "удаление цвета"], "a": 0, "e": "AAAAB → 4A1B."}]}}]}, {"title": "Программирование", "topics": [{"id": "i10-strings", "title": "Python: строки и обработка текста", "explain": "Строка — последовательность символов в кавычках. К символам обращаются по индексу s[0], берут срезы s[1:4], узнают длину len(s). Методы: upper(), lower(), replace(), split() (разбить на слова), join() (склеить), find(), count(). Строки неизменяемы — методы возвращают новую строку.", "check": true, "levels": {"easy": [{"q": "s = 'Python'. Чему равно s[0]?", "o": ["'P'", "'y'", "'n'", "0"], "a": 0, "e": "Индексы с нуля."}, {"q": "len('Астана')?", "o": ["6", "5", "7", "1"], "a": 0, "e": "Количество символов."}, {"q": "'abc'.upper()?", "o": ["'ABC'", "'abc'", "'Abc'", "ошибку"], "a": 0, "e": "Верхний регистр."}], "medium": [{"q": "'hello world'.split()?", "o": ["['hello', 'world']", "'hello world'", "['h', 'e', 'l', ...]", "ошибку"], "a": 0, "e": "Разбиение по пробелам."}, {"q": "s = 'информатика'. s[2:5]?", "o": ["'фор'", "'нфо'", "'форм'", "'инф'"], "a": 0, "e": "Индексы 2, 3, 4."}, {"q": "'мама'.count('ма')?", "o": ["2", "1", "4", "0"], "a": 0, "e": "Непересекающиеся вхождения."}], "hard": [{"q": "'-'.join(['a', 'b', 'c'])?", "o": ["'a-b-c'", "'abc'", "'-a-b-c-'", "['a-b-c']"], "a": 0, "e": "Склеивает через разделитель."}, {"q": "s = 'level'. Как проверить, что это палиндром?", "o": ["s == s[::-1]", "s == s", "s.reverse()", "len(s) % 2 == 0"], "a": 0, "e": "Срез с шагом −1."}, {"q": "'abc'.replace('b', 'x')?", "o": ["'axc'", "'abc'", "'xbc'", "ошибку"], "a": 0, "e": "Новая строка."}], "olympiad": [{"q": "Почему s[0] = 'A' вызывает ошибку для строки?", "o": ["строки неизменяемы", "индекс 0 не существует", "нужно двойные кавычки", "ошибки нет"], "a": 0, "e": "Создайте новую строку."}, {"q": "Что вернёт 'Python'.find('z')?", "o": ["-1", "0", "None", "ошибку"], "a": 0, "e": "Подстрока не найдена."}, {"q": "Сколько слов в строке 'Мен оқушымын және программистпін'?", "o": ["4", "3", "5", "33"], "a": 0, "e": "len(s.split())."}]}}, {"id": "i10-complexity", "title": "Анализ алгоритмов. Сложность", "explain": "Эффективность алгоритма оценивают по тому, как растёт число операций с ростом размера данных n — это асимптотическая сложность (O-нотация). O(1) — постоянное время, O(log n) — бинарный поиск, O(n) — линейный поиск, O(n log n) — быстрые сортировки, O(n²) — сортировка пузырьком, O(2ⁿ) — полный перебор подмножеств.", "check": true, "levels": {"easy": [{"q": "Сложность линейного поиска?", "o": ["O(n)", "O(1)", "O(log n)", "O(n²)"], "a": 0, "e": "Перебираем все элементы."}, {"q": "Сложность бинарного поиска?", "o": ["O(log n)", "O(n)", "O(n²)", "O(1)"], "a": 0, "e": "Деление пополам."}, {"q": "Доступ к элементу списка по индексу a[i] — это…", "o": ["O(1)", "O(n)", "O(log n)", "O(n²)"], "a": 0, "e": "Постоянное время."}], "medium": [{"q": "Сложность сортировки пузырьком?", "o": ["O(n²)", "O(n)", "O(log n)", "O(1)"], "a": 0, "e": "Вложенные циклы."}, {"q": "Во сколько раз дольше работает O(n²)-алгоритм, если n увеличить в 10 раз?", "o": ["в 100 раз", "в 10 раз", "в 20 раз", "в 2 раза"], "a": 0, "e": "10²."}, {"q": "Какой алгоритм эффективнее при больших n?", "o": ["O(n log n)", "O(n²)", "O(2ⁿ)", "O(n!)"], "a": 0, "e": "Растёт медленнее."}], "hard": [{"q": "Два вложенных цикла по n — какая сложность?", "o": ["O(n²)", "O(2n)", "O(n)", "O(log n)"], "a": 0, "e": "n · n операций."}, {"q": "Почему задачу коммивояжёра полным перебором не решить для 100 городов?", "o": ["число маршрутов растёт как факториал — астрономически", "не хватает городов", "компьютеры не умеют", "решается мгновенно"], "a": 0, "e": "100! — огромное число."}, {"q": "Цикл while n > 1: n //= 2 выполняется примерно…", "o": ["log₂ n раз", "n раз", "n² раз", "1 раз"], "a": 0, "e": "Деление пополам."}], "olympiad": [{"q": "Почему хеш-таблица (словарь Python) ищет элемент в среднем за O(1)?", "o": ["позиция вычисляется по хешу ключа", "она отсортирована", "она маленькая", "это не так"], "a": 0, "e": "Прямой доступ."}, {"q": "Сколько подмножеств у множества из 20 элементов?", "o": ["2²⁰ ≈ 1 млн", "20", "400", "20!"], "a": 0, "e": "Перебор подмножеств — O(2ⁿ)."}, {"q": "Что важнее для скорости программы на больших данных: быстрый компьютер или лучший алгоритм?", "o": ["обычно лучший алгоритм", "только компьютер", "ничего", "язык программирования"], "a": 0, "e": "O(n log n) против O(n²) — разница в тысячи раз."}]}}]}, {"title": "Информационная безопасность", "topics": [{"id": "i10-security", "title": "Информационная безопасность. Вредоносные программы", "explain": "Угрозы: вредоносные программы (вирусы, черви, трояны, шифровальщики), фишинг, утечки данных, социальная инженерия. Защита: антивирусы, обновления ПО, сложные уникальные пароли и менеджеры паролей, двухфакторная аутентификация, резервные копии, осторожность со ссылками и вложениями. В Казахстане защищает персональные данные закон «О персональных данных и их защите».", "check": true, "levels": {"easy": [{"q": "Что такое троянская программа?", "o": ["вредоносная программа, маскирующаяся под полезную", "антивирус", "браузер", "игра без вирусов"], "a": 0, "e": "Как троянский конь."}, {"q": "Что делает шифровальщик?", "o": ["шифрует файлы и требует выкуп", "ускоряет компьютер", "удаляет рекламу", "защищает пароли"], "a": 0, "e": "Ransomware."}, {"q": "Зачем делать резервные копии?", "o": ["чтобы восстановить данные при потере", "чтобы занять место", "для красоты", "не нужно"], "a": 0, "e": "Правило 3-2-1."}], "medium": [{"q": "Что такое социальная инженерия?", "o": ["обман людей для получения доступа к данным", "наука об обществе", "строительство", "программирование"], "a": 0, "e": "Например, звонок «из банка»."}, {"q": "Почему важно обновлять программы?", "o": ["обновления закрывают уязвимости", "чтобы изменился дизайн", "для рекламы", "не важно"], "a": 0, "e": "Патчи безопасности."}, {"q": "Что такое менеджер паролей?", "o": ["программа, хранящая уникальные сложные пароли", "блокнот", "антивирус", "браузер"], "a": 0, "e": "Запоминаете один главный пароль."}], "hard": [{"q": "Чем червь отличается от вируса?", "o": ["распространяется сам по сети без участия пользователя", "он безвреден", "он только в телефонах", "ничем"], "a": 0, "e": "Самостоятельное распространение."}, {"q": "Что такое DDoS-атака?", "o": ["перегрузка сервера огромным числом запросов", "кража пароля", "вирус в письме", "фишинг"], "a": 0, "e": "Отказ в обслуживании."}, {"q": "Что такое «нулевой день» (zero-day)?", "o": ["уязвимость, о которой ещё не знает производитель", "первый день года", "вирус-шутка", "отключение интернета"], "a": 0, "e": "Нет готового исправления."}], "olympiad": [{"q": "Почему длинная фраза-пароль надёжнее короткого сложного пароля?", "o": ["число вариантов растёт с длиной экспоненциально", "её легче взломать", "так требует закон", "это не так"], "a": 0, "e": "Энтропия пароля."}, {"q": "Что такое хеширование паролей на сервере?", "o": ["хранение не самого пароля, а его необратимого «отпечатка»", "шифрование с ключом", "удаление паролей", "отправка паролей по почте"], "a": 0, "e": "При утечке пароли не видны."}, {"q": "Что такое правило резервного копирования 3-2-1?", "o": ["3 копии, 2 разных носителя, 1 — в другом месте", "3 пароля, 2 логина, 1 почта", "3 антивируса", "такого нет"], "a": 0, "e": "Надёжная стратегия."}]}}]}]}, "11": {"sections": [{"title": "Программирование и данные", "topics": [{"id": "i11-oop", "title": "Объектно-ориентированное программирование", "explain": "ООП описывает программу как набор объектов. Класс — шаблон, объект — экземпляр класса. У объектов есть атрибуты (данные) и методы (действия). Основные принципы: инкапсуляция (скрытие внутреннего устройства), наследование (класс-потомок получает свойства родителя), полиморфизм (одинаковый интерфейс — разное поведение). В Python класс объявляют словом class, конструктор — метод __init__.", "check": true, "levels": {"easy": [{"q": "Что такое класс в ООП?", "o": ["шаблон для создания объектов", "объект", "переменная", "цикл"], "a": 0, "e": "Описание объектов."}, {"q": "Как называется метод-конструктор в Python?", "o": ["__init__", "__main__", "constructor", "init()"], "a": 0, "e": "Вызывается при создании объекта."}, {"q": "Что такое наследование?", "o": ["класс-потомок получает свойства и методы родителя", "копирование файла", "удаление класса", "цикл"], "a": 0, "e": "Повторное использование кода."}], "medium": [{"q": "Что такое инкапсуляция?", "o": ["скрытие внутренних деталей объекта", "наследование", "цикл", "сортировка"], "a": 0, "e": "Доступ через методы."}, {"q": "class Dog: def __init__(self, name): self.name = name. d = Dog('Бобик'). d.name?", "o": ["'Бобик'", "'Dog'", "self", "ошибку"], "a": 0, "e": "Атрибут объекта."}, {"q": "Что означает self в методах?", "o": ["ссылка на текущий объект", "имя класса", "глобальная переменная", "ключевое слово цикла"], "a": 0, "e": "Первый параметр метода."}], "hard": [{"q": "Что такое полиморфизм?", "o": ["разные классы реализуют одинаковый метод по-своему", "один класс", "ошибка", "удаление объектов"], "a": 0, "e": "Например, метод draw() у разных фигур."}, {"q": "class B(A): ... Что означает запись?", "o": ["класс B наследует класс A", "A наследует B", "B равен A", "ошибка"], "a": 0, "e": "Синтаксис наследования."}, {"q": "Сколько объектов можно создать из одного класса?", "o": ["сколько угодно", "один", "два", "ни одного"], "a": 0, "e": "Класс — шаблон."}], "olympiad": [{"q": "Зачем в больших проектах используют ООП?", "o": ["код легче структурировать, переиспользовать и поддерживать", "программы всегда быстрее", "это требование Python", "не используют"], "a": 0, "e": "Моделирование предметной области."}, {"q": "Что такое переопределение метода?", "o": ["потомок задаёт свою реализацию метода родителя", "удаление метода", "вызов метода дважды", "копирование класса"], "a": 0, "e": "Основа полиморфизма."}, {"q": "Что выведет: class A: x = 1. a = A(); b = A(); A.x = 5; print(b.x)?", "o": ["5", "1", "ошибку", "None"], "a": 0, "e": "Атрибут класса общий для объектов."}]}}, {"id": "i11-sql", "title": "Базы данных: язык SQL", "explain": "SQL — язык запросов к реляционным базам данных. SELECT выбирает данные, WHERE задаёт условие, ORDER BY сортирует, GROUP BY группирует, агрегатные функции COUNT, SUM, AVG, MAX, MIN считают итоги. JOIN объединяет таблицы по ключу. INSERT добавляет, UPDATE изменяет, DELETE удаляет записи.", "check": true, "levels": {"easy": [{"q": "Какая команда выбирает данные?", "o": ["SELECT", "INSERT", "DELETE", "UPDATE"], "a": 0, "e": "Запрос на выборку."}, {"q": "Какая команда добавляет запись?", "o": ["INSERT", "SELECT", "DROP", "WHERE"], "a": 0, "e": "INSERT INTO ..."}, {"q": "Что делает WHERE?", "o": ["задаёт условие отбора", "сортирует", "удаляет таблицу", "создаёт базу"], "a": 0, "e": "Фильтр."}], "medium": [{"q": "Средний балл в таблице grades?", "o": ["SELECT AVG(score) FROM grades", "SELECT SUM(score)", "SELECT score FROM avg", "AVG grades"], "a": 0, "e": "Агрегатная функция."}, {"q": "Что делает GROUP BY class?", "o": ["группирует записи по классу для подсчётов", "сортирует", "удаляет", "переименовывает"], "a": 0, "e": "Например, средний балл по классам."}, {"q": "Сортировка по убыванию?", "o": ["ORDER BY score DESC", "ORDER BY score ASC", "SORT score", "DESC score"], "a": 0, "e": "DESC — убывание."}], "hard": [{"q": "Что делает JOIN?", "o": ["объединяет строки двух таблиц по связанному полю", "удаляет дубликаты", "создаёт копию", "сортирует"], "a": 0, "e": "Например, ученики + классы."}, {"q": "Как изменить оценку ученика с id = 5?", "o": ["UPDATE grades SET score = 5 WHERE id = 5", "CHANGE grades 5", "SELECT score = 5", "INSERT score 5"], "a": 0, "e": "UPDATE ... SET ... WHERE."}, {"q": "Чем опасен DELETE FROM students без WHERE?", "o": ["удалит все записи таблицы", "ничего не удалит", "удалит одну запись", "вызовет ошибку"], "a": 0, "e": "Будьте внимательны."}], "olympiad": [{"q": "Чем отличается WHERE от HAVING?", "o": ["HAVING фильтрует группы после GROUP BY", "ничем", "HAVING сортирует", "WHERE работает после группировки"], "a": 0, "e": "Условие на агрегаты."}, {"q": "Что такое SQL-инъекция?", "o": ["атака через подстановку SQL-кода во входные данные", "быстрый запрос", "резервная копия", "вид JOIN"], "a": 0, "e": "Защита — параметризованные запросы."}, {"q": "Сколько строк вернёт SELECT DISTINCT city FROM students, если ученики из 3 разных городов?", "o": ["3", "число учеников", "1", "0"], "a": 0, "e": "DISTINCT убирает повторы."}]}}]}, {"title": "Искусственный интеллект и современные технологии", "topics": [{"id": "i11-ai", "title": "Искусственный интеллект и машинное обучение", "explain": "Искусственный интеллект — область информатики о создании систем, выполняющих задачи, требующие «разумного» поведения. Машинное обучение — подход, при котором программа учится на данных: с учителем (по примерам с правильными ответами), без учителя (поиск закономерностей), с подкреплением (по наградам). Нейронные сети лежат в основе распознавания изображений, речи и больших языковых моделей. Важны этика ИИ, честность данных и проверка фактов.", "check": true, "levels": {"easy": [{"q": "Что такое машинное обучение?", "o": ["обучение программы на данных", "ремонт компьютеров", "программирование роботов вручную", "печать"], "a": 0, "e": "Модель находит закономерности."}, {"q": "Что такое тест Тьюринга?", "o": ["проверка, может ли машина вести диалог неотличимо от человека", "экзамен по математике", "тест скорости процессора", "антивирус"], "a": 0, "e": "Предложен Аланом Тьюрингом в 1950 году."}, {"q": "Где применяют распознавание изображений?", "o": ["в медицине, транспорте, разблокировке телефона", "только в играх", "нигде", "в калькуляторах"], "a": 0, "e": "Компьютерное зрение."}], "medium": [{"q": "Обучение с учителем — это…", "o": ["обучение на примерах с известными правильными ответами", "без данных", "по наградам", "без ответов"], "a": 0, "e": "Например, фото с подписями."}, {"q": "Почему ИИ может «выдумывать» факты?", "o": ["языковая модель генерирует вероятный текст, а не проверяет истину", "это специально", "так требует закон", "не может"], "a": 0, "e": "Нужно проверять по источникам."}, {"q": "Что такое нейронная сеть?", "o": ["модель из связанных «нейронов», обучаемых на данных", "сеть компьютеров", "мозг человека", "интернет"], "a": 0, "e": "Вдохновлена устройством мозга."}], "hard": [{"q": "Что такое переобучение модели?", "o": ["модель запоминает обучающие данные и плохо работает на новых", "модель учится слишком долго всегда", "модель не учится", "обучение на новых данных"], "a": 0, "e": "Overfitting."}, {"q": "Почему данные для обучения должны быть разнообразными?", "o": ["иначе модель будет предвзятой", "чтобы было больше файлов", "так быстрее", "не важно"], "a": 0, "e": "Смещение (bias)."}, {"q": "Обучение с подкреплением — это…", "o": ["агент учится, получая награды и штрафы за действия", "обучение по картинкам", "без данных", "копирование кода"], "a": 0, "e": "Так учат играть в игры."}], "olympiad": [{"q": "Зачем данные делят на обучающую и тестовую выборки?", "o": ["чтобы честно проверить качество на данных, которых модель не видела", "чтобы было удобнее хранить", "так требует Python", "не делят"], "a": 0, "e": "Оценка обобщения."}, {"q": "Какая этическая проблема ИИ важна для школы?", "o": ["честность: работу должен выполнять ученик, а ИИ — помогать разобраться", "ИИ слишком медленный", "ИИ не умеет писать", "проблем нет"], "a": 0, "e": "Академическая честность."}, {"q": "Что такое «галлюцинация» языковой модели?", "o": ["уверенный, но неверный ответ", "ошибка компьютера", "сон компьютера", "вирус"], "a": 0, "e": "Всегда проверяйте источники."}]}}, {"id": "i11-crypto", "title": "Криптография и защита данных", "explain": "Криптография защищает информацию шифрованием. Симметричное шифрование использует один ключ для шифрования и расшифровки (шифр Цезаря — простой пример, AES — современный). Асимметричное шифрование (RSA) использует пару ключей: открытый для шифрования и закрытый для расшифровки. Цифровая подпись подтверждает автора и неизменность документа; в Казахстане широко используется ЭЦП.", "check": true, "levels": {"easy": [{"q": "Что такое шифрование?", "o": ["преобразование данных, делающее их непонятными без ключа", "сжатие файла", "удаление", "печать"], "a": 0, "e": "Конфиденциальность."}, {"q": "Что такое ЭЦП?", "o": ["электронная цифровая подпись", "электронная почта", "пароль от Wi-Fi", "антивирус"], "a": 0, "e": "Используется на eGov."}, {"q": "Шифр Цезаря со сдвигом 1: «АБВ» → ?", "o": ["«БВГ»", "«ЯАБ»", "«ВГД»", "«АБВ»"], "a": 0, "e": "Каждая буква сдвигается на 1."}], "medium": [{"q": "Чем асимметричное шифрование отличается от симметричного?", "o": ["используются два ключа: открытый и закрытый", "ключ не нужен", "один ключ", "ничем"], "a": 0, "e": "RSA."}, {"q": "Почему шифр Цезаря легко взломать?", "o": ["всего несколько десятков возможных сдвигов", "он новый", "он сложный", "нельзя взломать"], "a": 0, "e": "Полный перебор."}, {"q": "Что гарантирует цифровая подпись?", "o": ["авторство и неизменность документа", "секретность", "сжатие", "скорость"], "a": 0, "e": "Проверяется открытым ключом."}], "hard": [{"q": "Какой ключ в RSA можно публиковать?", "o": ["открытый", "закрытый", "оба", "никакой"], "a": 0, "e": "Им шифруют сообщения для владельца."}, {"q": "Что такое частотный анализ?", "o": ["взлом шифра замены по частоте букв", "измерение частоты процессора", "анализ звука", "сжатие"], "a": 0, "e": "Самые частые буквы."}, {"q": "Почему HTTPS безопасен?", "o": ["данные между браузером и сервером шифруются", "сайт быстрее", "нет рекламы", "сайт бесплатный"], "a": 0, "e": "TLS-шифрование."}], "olympiad": [{"q": "На какой математической задаче основана стойкость RSA?", "o": ["сложности разложения больших чисел на простые множители", "сложении", "делении на 2", "таблице умножения"], "a": 0, "e": "Факторизация."}, {"q": "Расшифруйте шифр Цезаря со сдвигом 3: «НСХ» (русский алфавит с Ё)", "o": ["«КОТ»", "«ЛПУ»", "«МРФ»", "«ЙНС»"], "a": 0, "e": "Сдвигаем каждую букву на 3 назад: Н→К, С→О, Х→Т."}, {"q": "Почему квантовые компьютеры угрожают RSA?", "o": ["алгоритм Шора может быстро раскладывать числа на множители", "они быстрее печатают", "они не угрожают", "из-за энергии"], "a": 0, "e": "Постквантовая криптография."}]}}, {"id": "i11-project", "title": "Разработка программных проектов. Цифровая грамотность", "explain": "Создание программ проходит этапы: постановка задачи, проектирование, программирование, тестирование, внедрение и сопровождение. Команды используют системы контроля версий (Git), пишут тесты, проводят код-ревью. Цифровая грамотность включает умение критически оценивать информацию, соблюдать авторские права (лицензии Creative Commons, открытый код) и цифровой этикет.", "check": true, "levels": {"easy": [{"q": "Что такое Git?", "o": ["система контроля версий", "язык программирования", "браузер", "игра"], "a": 0, "e": "Хранит историю изменений."}, {"q": "Что такое тестирование программы?", "o": ["проверка, что программа работает правильно", "написание кода", "покупка программы", "удаление программы"], "a": 0, "e": "Поиск ошибок."}, {"q": "Что такое баг?", "o": ["ошибка в программе", "насекомое в компьютере всегда", "новая функция", "вирус"], "a": 0, "e": "Термин из истории."}], "medium": [{"q": "Что такое открытый исходный код?", "o": ["код, который можно читать, изменять и распространять по лицензии", "секретный код", "код без ошибок", "код на бумаге"], "a": 0, "e": "Например, Linux, Python."}, {"q": "Что такое коммит в Git?", "o": ["сохранённый снимок изменений с описанием", "удаление файла", "ветка", "сервер"], "a": 0, "e": "git commit."}, {"q": "Что такое лицензия Creative Commons?", "o": ["набор условий, на которых автор разрешает использовать работу", "запрет на использование", "налог", "пароль"], "a": 0, "e": "Например, CC BY."}], "hard": [{"q": "Зачем нужны ветки (branches) в Git?", "o": ["вести разработку параллельно, не ломая основную версию", "удалять код", "ускорять компьютер", "не нужны"], "a": 0, "e": "Фичи разрабатывают в отдельных ветках."}, {"q": "Что такое код-ревью?", "o": ["проверка кода другими разработчиками", "запуск программы", "написание документации", "оплата"], "a": 0, "e": "Повышает качество."}, {"q": "Что такое модульное (unit) тестирование?", "o": ["проверка отдельных функций программы", "проверка всего компьютера", "тест скорости интернета", "экзамен"], "a": 0, "e": "Автоматические тесты."}], "olympiad": [{"q": "Что такое Agile/Scrum?", "o": ["гибкие методологии разработки короткими итерациями", "язык программирования", "антивирус", "вид базы данных"], "a": 0, "e": "Спринты."}, {"q": "Почему нельзя публиковать в открытом репозитории пароли и API-ключи?", "o": ["их найдут и используют злоумышленники", "репозиторий станет медленнее", "так требует Git", "можно"], "a": 0, "e": "Секреты хранят отдельно."}, {"q": "Как проверить достоверность информации из интернета?", "o": ["сравнить несколько надёжных источников и проверить автора и дату", "поверить первому сайту", "спросить в комментариях", "не проверять"], "a": 0, "e": "Критическое мышление."}]}}]}]}}};
